using ElectronicRegisterAPI.Domain.Enums;

namespace ElectronicRegisterAPI.Domain.Models;

// Institution-scoped account creation. The institution always comes from the
// authenticated tenant, never from the request; the address is generated by the server.
public sealed record CreateInstitutionAccount(
    Guid EventId,
    string FirstName,
    string LastName,
    string FiscalCode,
    InstitutionRole[] Roles,
    Guid? StudentId,
    Guid? TeacherId,
    Guid? ClassId,
    string Reason
);
